function remember(){history.push({ids:[...pool],params:{...params}});if(history.length>30)history.shift();}
function add(ids){remember();let count=0;ids.forEach(id=>{const c=CATALOG.find(c=>c.id===id);if(!c)return;if(!pool.has(id)){count++;if(c.sceneDefaults)params={...params,...c.sceneDefaults};}pool.add(id);(c.models||[]).forEach(m=>pool.add(m));staged.delete(id);});render();announce(`已加入 ${count} 張卡片，評估已更新。`);toast('已加入評估池 · 場景建議技術一併帶入');}
