 if(w)html+=`<div class="result-main"><div class="status"><span class="rank-label">#1</span><i class="dot wait"></i>優先 PoC · 尚待真機驗證</div><h3>${w.name}</h3><div class="route">${w.vendor} / ${w.route} · 採購 ${COST_BANDS[w.costBand].label}</div>${deviceArt(w)}<ul class="reasons">${w.why.slice(0,2).map(x=>`<li>${esc(x.replace(/（優先權.*$/,''))}</li>`).join('')}</ul><button data-device="${w.id}">展開推薦理由與待驗證條件</button><div class="result-meta">${w.checks.length} 項待查核 · 沒有 FPS 達標保證</div></div>`;
 else html+=`<div class="empty-result"><h3>${e.issues.length?'目前無可推薦組合':'先建立你的評估池'}</h3><p>${e.issues.length?'修正左方條件後，這裡會重新產生候選。':'加入場景會帶入建議技術，再加入功耗、相機或部署限制。'}</p></div>`;
 if(e.models.length&&e.scenes.length)html+=`<div class="result-section"><h3>${w?'其他候選與排除原因':'候選預檢 · 尚未推薦'}</h3>${e.candidates.filter(d=>(!w||d.id!==w.id)&&(!e.aiot?.standalone||d.family==='mcu')).map(d=>`<button class="candidate-row" data-device="${d.id}"><span class="rank-label">${d.blocked.length?'—':'#'+(e.candidates.filter(c=>!c.blocked.length).findIndex(c=>c.id===d.id)+1)}</span>${DEVICE_IMAGES[d.id]?`<img class="candidate-photo" src="${DEVICE_IMAGES[d.id]}" alt="${d.vendor} 官方產品圖" loading="lazy">`:""}<span><strong>${d.name}</strong><small>${d.vendor} · 採購 ${(COST_BANDS[d.costBand]?.label||'—')} · 點擊查看依據</small></span><span class="badge ${d.blocked.length?'bad':''}">${d.blocked.length?'已排除':'待 PoC'}</span></button>`).join('')}</div>`;
 if(e.aiot?.standalone)html+='<p class="small-note">端點範圍不需大型主機；品牌排除原因見下方完整流程。</p>';
 if(e.scenes.length)html+=`<div class="result-section"><h3>場景落地示例</h3>${e.scenes.slice(0,1).map(c=>`<div class="example">${sceneArtwork(c)?`<img class="scene-preview" src="${sceneArtwork(c)}" alt="${c.name}原創概念示意，非實測">`:''}<strong>${c.name}</strong><p>${c.story}</p><div class="pipeline">${c.pipeline.map((s,i)=>(i?'<i>→</i>':'')+`<span>${s}</span>`).join('')}</div><button class="text-button" data-info="${c.id}">檢視驗收與場景假設</button></div>`).join('')}${e.scenes.slice(1).map(c=>`<button class="scenario-link" data-info="${c.id}"><span>${c.name}示例</span><span>↗</span></button>`).join('')}</div>`;
 if(e.models.length&&!e.aiot?.standalone)html+=`<details><summary>容量與未解條件</summary>${e.detectorOps!==null?`<p>YOLOv8${params.modelSize} / 640：${e.detectorOps.toFixed(3)} TFLOP/s 理論模型負載。${e.streams} 路 × ${params.inferFps} FPS；未含追蹤、VLM、深度、搬移與利用率，不等於硬體 TOPS 下限。</p>`:'<p>此模型組合尚無足夠資料估算硬體容量，請先取得真機 profile。</p>'}${e.pending.map(x=>`<p>待補：${esc(x)}</p>`).join('')}<p>排序優先權是公開的規則權重，不是效能測量或成功機率。</p><button class="text-button" data-info="rules">檢視完整排序規則</button></details>`;
 html+=productFlow();$('result').innerHTML=html;syncConflictHighlights();
