function showInfo(id){const c=CATALOG.find(c=>c.id===id);if(c){openDrawer(c.name,`${sceneArtwork(c)?`<img class="scene-preview" src="${sceneArtwork(c)}" alt="${c.name}概念示意">`:''}${c.story?`<p>${esc(c.story)}</p>`:''}<p>${esc(c.detail)}</p>${c.pipeline?`<div class="pipeline">${c.pipeline.map((s,i)=>(i?'<i>→</i>':'')+`<span>${s}</span>`).join('')}</div>`:''}<button class="primary" data-add="${c.id}" ${pool.has(c.id)?'disabled':''}>${pool.has(c.id)?'已在評估池':'加入評估池'}</button>${referenceLinks(c)}<p>${c.source?` · <a href="${c.source}" target="_blank" rel="noopener">官方依據 ↗</a>`:''}</p>`);return;}
 if(id==='help')openDrawer('用卡片組合需求','<p>先選一張場景，系統會帶入建議技術；技術可以各自移除或替換。</p><div class="method-tree"><div>拖拉單張卡片<small>拖到綠色評估池，加入後即時更新。</small></div><div>多選 → 一起拖入<small>勾選卡片後拖曳其中一張，或按「加入已選」。</small></div><div>懸停預覽 → 點擊詳情<small>資訊圖示在滑鼠與鍵盤聚焦時出現提示；詳細內容在側窗。</small></div><div>右鍵卡片<small>開啟加入／介紹選單；同樣的功能也可直接點擊，手機不必長按。</small></div></div><p>選多個場景表示同一輸入共用模型。模型卡並存代表都需要運行；比較替代方案時請先移除另一個模型。</p>');
 else if(id==='rules')openDrawer('本次排名依據',`<p>先排除框架、容量及路徑不合的配置，再比較可查證部署方向。數值是規劃優先權，不是性能或成功率。</p>${evaluation.candidates.map(d=>`<h3>${d.name} · ${d.score}</h3><ul>${[...d.why,...d.blocked.map(x=>'排除：'+x)].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<p>硬性限制先排除；依所選技術或採購優先排序，同分以採購等級，再以資料順序處理。未知功耗與延遲保留待驗證。</p>`);
 else if(id==='conflicts')openDrawer('修正條件，而非加大 TOPS',`<ul>${evaluation.issues.map((i,n)=>`<li>${esc(i.text)} <button data-fix-conflict="${n}">前往修改 ↗</button></li>`).join('')}</ul><p>若相機未拍到足夠紋理，提高算力無法補回資訊。若推論頻率不足，先確認 causal / window 版本、點數、輸入大小，再評估平台。</p><button class="text-button" id="drawerMethod">查看完整思考流程</button>`);
}
function showDevice(id){const d=evaluation.candidates.find(d=>d.id===id)||evaluation.aiot?.endpoints.find(d=>d.id===id);if(!d)return;openDrawer(d.name,`${deviceArt(d)}<p>${d.note}</p><h3>${d.blocked.length?'排除原因':'優先權依據'}</h3><ul>${(d.blocked.length?d.blocked:d.why.length?d.why:['此組合無額外加權；仍可進行工程評估。']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>進入採購前要補齊</h3><ul>${d.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>採購等級 ${(COST_BANDS[d.costBand]?.label||'—')} · 規劃優先權 ${d.score}，不代表效能排名。${d.ram?`此配置 ${d.ram} GB RAM。`:'RAM 依實際板卡確認。'}</p><a href="${d.source}" target="_blank" rel="noopener">官方產品／相容性依據 ↗</a>`);}
function method(){openDrawer('先理解需求，再選算力',`<p>靜態／動態決定觀測方式；即時／非即時決定時間期限。兩個維度分開判斷。</p><div class="method-tree"><div>使用者要完成什麼？<small>輸出、精度、失敗代價</small></div><span class="tree-arrow">↓</span><div class="split"><span>靜態<small>文件、定點工件</small></span><span>動態<small>人流、軌跡、影片</small></span></div><span class="tree-arrow">↓ 兩者都可能需要即時</span><div class="split"><span>即時<small>FPS + P95 + 排隊</small></span><span>按需／離線<small>節拍或批次完成時間</small></span></div><span class="tree-arrow">↓</span><div>相機是否看得清楚？<small>特徵像素、曝光、幀間位移；不行先改光學。</small></div><span class="tree-arrow">↓</span><div>選最小可行的演算法<small>物件框 → YOLO；逐點 → TAPIR；遮罩 → SAM；語意 → VLM。</small></div><span class="tree-arrow">↓</span><div>算子與版本能否部署？<small>export → compile → partition → fallback；不行則改圖、backend 或平台。</small></div><span class="tree-arrow">↓</span><div>量測整機容量與功耗<small>FPS、P95、RAM、I/O、散熱、精度都達標才選型。</small></div></div><p><a href="edge-ai-decision.drawio" download>下載原始三頁 draw.io</a> · <button class="text-button" data-export="drawio">匯出本次決策圖</button></p>`);}
function showRefs(){openDrawer('13 個深入參考主題',`<p>工作台用來探索；參考圖譜用來追溯技術和驗收依據。</p>${REFS.map(([id,name],i)=>`<a class="ref-row" href="reference.html#${id}" target="_blank" rel="noopener"><span>${String(i+1).padStart(2,'0')}</span>${name}<span>↗</span></a>`).join('')}`);}
function place(el,x,y){el.style.left=Math.max(8,Math.min(x,window.innerWidth-el.offsetWidth-12))+'px';el.style.top=Math.max(8,Math.min(y,window.innerHeight-el.offsetHeight-12))+'px';}
function hideTip(){clearTimeout(tipTimer);$('tooltip').hidden=true;if(tipOwner)tipOwner.removeAttribute('aria-describedby');tipOwner=null;}
function showTip(el){if(!el.isConnected)return;hideTip();tipOwner=el;$('tooltip').textContent=el.dataset.tip;$('tooltip').hidden=false;el.setAttribute('aria-describedby','tooltip');const r=el.getBoundingClientRect();place($('tooltip'),r.left,r.bottom+7);}
function openContext(id,x,y){contextId=id;contextOrigin=document.querySelector(`[data-card="${id}"] .card-main`)||document.querySelector(`[data-card="${id}"] button`)||$('pool');$('contextAdd').textContent=pool.has(id)?'從評估池移除':'加入評估池';$('contextMenu').hidden=false;place($('contextMenu'),x,y);$('contextAdd').focus();}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('評估檔案已產生');}
function report(){const e=evaluation;return ['# Edge AI 評估紀錄','',`產生時間：${new Date().toISOString()}`,'','## 已選需求',...CATALOG.filter(c=>pool.has(c.id)).map(c=>`- ${GROUPS[c.group]}：${c.name}`),'','## 輸入條件','```json',JSON.stringify(params,null,2),'```','','## 同時運行資源預算',JSON.stringify(e.resources,null,2),...(e.aiot?['',AIOT.T('scope'),...e.aiot.endpoints.flatMap(d=>[d.name,...d.blocked,...d.checks]),AIOT.T('memory')+': '+e.aiot.workingMB.toFixed(2)+' MB']:[]),'','## 決策過程',...e.stages.map(s=>`- ${s.name}：${s.value} — ${s.text}`),'','## 場景深入約束',...e.requirements.map(r=>`- ${r.name}：${r.text}`),'','## 條件衝突',...(e.issues.length?e.issues.map(i=>`- ${i.text}`):['無已知輸入衝突；不代表已驗證可行。']),'','## 優先 PoC',e.winner?.name||'尚無可推薦組合','',...e.candidates.flatMap(d=>[`### ${d.name} — ${d.blocked.length?'排除':'條件式候選'}`,`規劃優先權 ${d.score}（不是實測效能） / 採購等級 ${(COST_BANDS[d.costBand]?.label||'—')}`,...d.why.map(s=>'- '+s),...d.blocked.map(s=>'- 排除：'+s),...d.checks.map(s=>'- 待驗證：'+s),`來源：${d.source}`,'']),'## 場景示例',...e.scenes.flatMap(c=>[c.name,c.story,c.pipeline.join(' → '),'']),'## 限制','本工具使用規則推導；未執行真機 benchmark。多場景假設同一輸入共享模型，不同管線請分開評估。','官方依據查閱：2026-10-14。'].join('\n');}
function exportDrawio(){const e=evaluation;
 const nodes=[
 ['goal','產品輸出 / 場景',e.scenes.map(s=>s.name).join(' + ')||'待選擇',250,20,300,70],
 ['sense','感知與物理限制',e.requirements.filter(r=>/取像|相機|公尺/.test(r.name)).map(r=>r.text).join('\n')||'非視覺／感知条件待定',20,125,350,100],
 ['budget','時間與資源',e.speech?`${params.speechDeadline} ms / ${params.responseMetric}\n${e.requirements.find(r=>r.name==='語音回應期限')?.text||''}`:`${params.inferFps} FPS / ${pool.has('power')?params.watts+' W':'功耗待定'} / 並存 ${e.resources.totalGB.toFixed(1)} GB`,430,125,350,100],
 ['tech','技術与框架',e.models.map(m=>CATALOG.find(c=>c.id===m).name).join(' + ')+(e.llm?'\n'+(e.llm.cloud?'雲端 API':params.llmRuntime):''),180,265,440,80],
 ['gate','需求相容性預檢',e.issues.length?e.issues.map(i=>i.text).join('\n'):'未發現輸入衝突；算子與效能仍待實測',180,390,440,110],
 ['exclude','硬性篩除',e.candidates.filter(d=>d.blocked.length).map(d=>d.name+': '+d.blocked.join(' / ')).join('\n')||'無已知硬性排除',20,550,350,140],
 ['rank','候選優先權',e.candidates.filter(d=>!d.blocked.length).slice(0,4).map((d,i)=>`#${i+1} ${d.name} / 規劃權重 ${d.score}`).join('\n'),430,550,350,140],
 ['recommend','裝置建議',e.winner?.name||'先修正輸入／技術路徑衝突',180,740,440,75],
 ['poc','真機驗收', '分段精度 → P95 / FPS → 峰值 RAM\n整機功耗 → 熱穩態 → 失效處置\n達標後才定型',180,860,440,100]
 ];
 if(e.aiot){nodes.push(['endpoint',AIOT.T('scope'),e.aiot.endpoints.map(d=>d.name+': '+(d.blocked.join(' / ')||'PoC')).join('\n')+'\n'+e.aiot.workingMB.toFixed(2)+' MB PSRAM',840,125,400,220]);}
 const links=[['goal','sense'],['goal','budget'],['sense','tech'],['budget','tech'],['tech','gate'],['gate','exclude'],['gate','rank'],['exclude','recommend'],['rank','recommend'],['recommend','poc']];
 if(e.aiot)links.push(['goal','endpoint'],['endpoint','gate']);
 let cells='<mxCell id="0"/><mxCell id="1" parent="0"/>';
 for(const [id,title,body,x,y,w,h] of nodes)cells+=`<mxCell id="${id}" value="${esc(title+'\n'+body)}" style="rounded=1;whiteSpace=wrap;html=0;fillColor=${id==='gate'&&e.issues.length?'#ffe5df':'#edf3e8'};strokeColor=#789b87;fontSize=12;" vertex="1" parent="1"><mxGeometry x="${x}" y="${y}" width="${w}" height="${h}" as="geometry"/></mxCell>`;
 const branchY=750;
 e.candidates.forEach((d,i)=>{const id='device-'+d.id;cells+=`<mxCell id="${id}" value="${esc(d.name+' / '+(d.blocked.length?'排除':e.winner?.id===d.id?'排名1':'保留候選')+'\n'+('採購等級 '+(COST_BANDS[d.costBand]?.label||'—')+' / 並存 '+e.resources.totalGB.toFixed(1)+' GB\n'+candidateExplanation(d).join('\n')))}" style="rounded=1;whiteSpace=wrap;html=0;fillColor=${d.blocked.length?'#ffe5df':e.winner?.id===d.id?'#d9eddf':'#f3f3ee'};strokeColor=#789b87;fontSize=11;" vertex="1" parent="1"><mxGeometry x="${i%3*265+10}" y="${branchY+Math.floor(i/3)*175}" width="250" height="145" as="geometry"/></mxCell>`;links.push(['gate',id]);if(e.winner?.id===d.id)links.push([id,'recommend']);});
 const finalY=branchY+Math.ceil(e.candidates.length/3)*175+20;
 cells=cells.replace('x="180" y="740"','x="180" y="'+finalY+'"').replace('x="180" y="860"','x="180" y="'+(finalY+120)+'"');
 links.forEach(([a,b],i)=>cells+=`<mxCell id="e${i}" style="edgeStyle=orthogonalEdgeStyle;endArrow=block;" edge="1" parent="1" source="${a}" target="${b}"><mxGeometry relative="1" as="geometry"/></mxCell>`);
 return `<?xml version="1.0" encoding="UTF-8"?><mxfile host="app.diagrams.net"><diagram name="完整產品選型"><mxGraphModel dx="800" dy="1000" grid="1" page="1" pageWidth="800" pageHeight="1700"><root>${cells}</root></mxGraphModel></diagram></mxfile>`;
}
function exportPanel(){openDrawer('匯出本次評估',`<p>包含已選卡片、輸入參數、推薦依據、排除原因與待驗證清單。</p><button class="primary" data-export="md">下載評估報告 .md</button><button data-export="json">下載評估資料 .json</button> <button data-export="drawio">下載決策圖 .drawio</button><h3>會議或列印</h3><p>瀏覽器列印會保留評估池、判斷路徑與候選。完整條件請使用報告。</p><button data-export="print">列印目前評估</button>`);}
$('search').addEventListener('input',renderCatalog);
$('addSelected').addEventListener('click',()=>add([...staged]));
$('clear').addEventListener('click',()=>{remember();pool.clear();staged.clear();render();toast('已清空，可按復原還原');});
$('undo').addEventListener('click',()=>{const old=history.pop();if(!old)return;pool=new Set(old.ids);params={...old.params};render();});
$('preset').addEventListener('change',e=>{const known=PLATFORM_CASES.find(c=>c.id===e.target.value);const preset=known?{ids:known.ids,p:known.params}:presets[e.target.value];caseContext=known||null;if(!preset)return;remember();pool=new Set(preset.ids);staged.clear();params={...DEFAULTS,...preset.p};render();toast('已套用範例 · 數值是起測假設');e.target.value='';});
$('methodBtn').onclick=method;$('referenceBtn').onclick=showRefs;$('exportBtn').onclick=exportPanel;$('closeDrawer').onclick=closeDrawer;
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!e.target.closest('#contextMenu'))$('contextMenu').hidden=true;if(!b)return;
 if(b.dataset.fixConflict!==undefined){focusConflict(Number(b.dataset.fixConflict));return;}
 if(b.dataset.resolution){remember();[params.sensorWidth,params.sensorHeight]=b.dataset.resolution.split(',').map(Number);evaluation=evaluate([...pool],params);renderTuning();refreshEvaluation();}
 if(b.dataset.deadline){remember();params.speechDeadline=Number(b.dataset.deadline);evaluation=evaluate([...pool],params);renderTuning();refreshEvaluation();}
 if(b.dataset.group){group=b.dataset.group;$('search').value='';document.querySelectorAll('[data-group]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderCatalog();}
 if(b.dataset.add){add([b.dataset.add]);if(!$('drawer').hidden){b.disabled=true;b.textContent='已在評估池';}}
 if(b.dataset.remove)remove(b.dataset.remove);
 if(b.dataset.info)showInfo(b.dataset.info);
 if(b.dataset.device)showDevice(b.dataset.device);
 if(b.dataset.stage){const s=evaluation.stages[Number(b.dataset.stage)];openDrawer(`${s.name}：${s.value}`,`<p>${esc(s.text)}</p><p>狀態：${s.state==='bad'?'條件衝突':s.state==='ok'?'條件已輸入，未代表真機通過':'待驗證'}</p><button class="text-button" id="drawerMethod">查看完整思考流程</button>`);}
 if(b.dataset.fieldInfo){const f=fields[b.dataset.fieldInfo];openDrawer(f[0],`<p>${f[3]}</p>`);}
 if(b.id==='drawerMethod')method();
 if(b.dataset.export){const type=b.dataset.export;if(type==='md')download('edge-ai-assessment.md',translateText(report()),'text/markdown;charset=utf-8');if(type==='json')download('edge-ai-assessment.json',JSON.stringify({schema:1,created:new Date().toISOString(),...evaluation},null,2),'application/json');if(type==='drawio')download('edge-ai-assessment.drawio',localizedHTML(exportDrawio()),'application/xml');if(type==='print')window.print();}
});
document.addEventListener('change',e=>{ const t=e.target;if(t.dataset.cost){remember();params.costOverrides={...params.costOverrides,[t.dataset.cost]:t.value};refreshEvaluation();}
 if(t.dataset.budget){remember();const id=t.dataset.budget,key=t.dataset.budgetKey;const val=key==='place'?t.value:t.value.trim()===''?(key==='timeMs'?null:NaN):Number(t.value);const old=params.modelBudgets[id]||{};params.modelBudgets={...params.modelBudgets,[id]:key==='timeMs'?{...old,timings:{...old.timings,[params.profileDevice]:val}}:{...old,[key]:val}};refreshEvaluation();}if(e.target.dataset.select){const id=e.target.dataset.select;e.target.checked?staged.add(id):staged.delete(id);e.target.closest('.card').classList.toggle('staged',e.target.checked);$('selectionCount').textContent=staged.size?`已選 ${staged.size} 張`:'可多選拖入';$('addSelected').disabled=!staged.size;}if(e.target.dataset.param){remember();const k=e.target.dataset.param;if(['mcuVision','mcuCamera','mcuWidth','mcuHeight','mcuBuffers','mcuPixelBytes','mcuModelMB','mcuUiMB','mcuReserveMB','iotRadio','iotTransport'].includes(k)){params.mcuMeasuredS3=0;params.mcuMeasuredP4=0;}params[k]=e.target.tagName==='SELECT'?e.target.value:(e.target.value.trim()===''?NaN:Number(e.target.value));if(k==='companionBackend'&&params[k]==='muse'&&!pool.has('iotlocal')&&!pool.has('voiceagent')&&!pool.has('ragagent')){for(const id of ['llm','asr','tts','localstack','audio'])pool.delete(id);renderPool();}if(k==='companionBackend'&&params[k]==='local'){for(const id of ['llm','asr','tts','localstack','audio'])pool.add(id);params={...params,...AIOT.data.scenes.find(c=>c.id==='iotlocal').sceneDefaults};renderPool();}if(k==='depthMode'&&['stereo','tof','fusion'].includes(params[k])){pool.add('stereo');renderPool();}if(['companionBackend','iotReply','mcuVision','mcuCamera','mcuWidth','mcuHeight','mcuBuffers','mcuPixelBytes','mcuModelMB','mcuUiMB','mcuReserveMB','iotRadio','iotTransport','profileDevice','llmMemoryPlace','llmPlacement','decisionPlacement','llmProfile','llmRuntime','depthMode','depthUse','responseMetric','pixelMode','cameraPlatform','stabilization'].includes(k)){const activeId=e.target.id;evaluation=evaluate([...pool],params);renderTuning();if(activeId&&$(activeId))$(activeId).focus();}refreshEvaluation();}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-card]');if(!card)return;const ids=staged.has(card.dataset.card)?[...staged]:[card.dataset.card];e.dataTransfer.setData('application/x-edge-cards',JSON.stringify(ids));e.dataTransfer.setData('text/plain',JSON.stringify(ids));e.dataTransfer.effectAllowed='copy';hideTip();});
$('pool').addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';$('pool').classList.add('drag-over');});
$('pool').addEventListener('dragleave',e=>{if(!$('pool').contains(e.relatedTarget))$('pool').classList.remove('drag-over');});
$('pool').addEventListener('drop',e=>{e.preventDefault();$('pool').classList.remove('drag-over');try{const ids=JSON.parse(e.dataTransfer.getData('application/x-edge-cards')||e.dataTransfer.getData('text/plain'));if(Array.isArray(ids))add(ids.filter(x=>typeof x==='string'));}catch{toast('請拖入工作台內的需求卡片');}});
document.addEventListener('contextmenu',e=>{const card=e.target.closest('[data-card]');if(!card)return;e.preventDefault();hideTip();openContext(card.dataset.card,e.clientX,e.clientY);});
$('contextAdd').onclick=()=>{pool.has(contextId)?remove(contextId):add([contextId]);$('contextMenu').hidden=true;$('pool').focus();};
$('contextInfo').onclick=()=>{$('contextMenu').hidden=true;showInfo(contextId);drawerOrigin=contextOrigin;};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideTip();if(!$('contextMenu').hidden){$('contextMenu').hidden=true;$('pool').focus();}else if(!$('drawer').hidden)closeDrawer();}if(!$('contextMenu').hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...$('contextMenu').querySelectorAll('button')];const current=buttons.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(current+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();}if((e.shiftKey&&e.key==='F10')||e.key==='ContextMenu'){const c=e.target.closest('[data-card]');if(c){e.preventDefault();const r=c.getBoundingClientRect();openContext(c.dataset.card,r.left,r.bottom);}}});
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-tip]');if(el&&!el.contains(e.relatedTarget)){clearTimeout(tipTimer);tipTimer=setTimeout(()=>showTip(el),380);}if(e.target.closest('#tooltip'))clearTimeout(tipTimer);});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip],#tooltip')){clearTimeout(tipTimer);tipTimer=setTimeout(hideTip,180);}});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-tip]'))showTip(e.target);});
document.addEventListener('focusout',e=>{if(e.target.matches('[data-tip]'))hideTip();});
window.addEventListener('resize',()=>{hideTip();$('contextMenu').hidden=true;});
window.addEventListener('scroll',hideTip,true);
const DEVICE_IMAGES=/*DEVICEIMAGES*/{};
const DEVICE_CAPTIONS=/*DEVICECAPTIONS*/{};
const MORE_FIELDS={viewDistance:['拍攝 / 觀測距離 m',.1,10000,'遠距目標到相機的距離，與避障驗收近遠點可不同。'],objectMeters:['物件實際寬 m',.01,100,'以 pinhole 幾何粗估像素；若實拍可量測，以像素模式優先。'],objectHeightMeters:['物件實際高 m',.01,100,'中心附近、方形像素的簡化投影；廣角與魚眼需標定模型。'],audioPlaybackMs:['完整回答播放時長 ms',0,600000,'完整語音完成包含音訊播放本身；此欄以目標內容的實測／預估時長輸入。'],
 sensorHeight:['畫面高度 px',1,20000,'與寬度合成實拍畫面；1280×720 需同時指定。'],objectWidth:['目標框寬 px',.1,20000,'原圖中物件寬度，不是框選後的放大預覽。'],objectHeight:['目標框高 px',.1,20000,'物件在原始畫面中實際占用的像素。'],fov:['水平 FOV °',1,179,'幾何換算假設 pinhole、畫面中心附近；魚眼需另用標定模型。'],angularSpeed:['相機角速度 °/s',0,1000,'填寫 gimbal 後的實際殘餘角速度；系統不自動假設雲台完全穩定。'],imuSyncMs:['IMU / 相機同步誤差 ms',0,1000,'影像與角速度 timestamp 的最大差異。'],trackingPoints:['追蹤點數',1,10000,'點數影響 correlation、attention、state 與記憶體；需指定 checkpoint profile。'],smallDefectPx:['最小缺陷寬 px',.1,10000,'原圖最小可驗收缺陷；分塊處理會提高模型呼叫次數。'],nearDistance:['近距驗收點 m',.05,1000,'指定需要嚴格公尺精度的近距離位置。'],nearError:['近距誤差上限 ±m',.001,100,'自訂精度標準；需另外定義 P95 或最大誤差。'],farDistance:['最遠有效感知 m',.1,1000,'遠距驗收測點，也用於比較煞停距離。'],farError:['遠距誤差上限 ±m',.001,100,'可與近距採不同絕對誤差預算。'],baselineMm:['Stereo baseline mm',1,1000,'兩個相機光心間距。'],focalPx:['校正後焦距 px',1,20000,'校正相機矩陣 fx；與 FOV 估算值分開，避免混用不同輸入。'],disparityError:['disparity 誤差 px',.01,20,'幾何起測假設；不是完整模型或感測器誤差。'],robotSpeed:['行進速度 m/s',0,100,'移動本體速度，與影像平面的 px/s 分開。'],deceleration:['可用減速度 m/s²',.01,100,'須由機械控制與載重驗證。'],margin:['額外距離餘量 m',0,100,'初期规划距離，不能代替安全分析。'],weightBits:['權重量化 bits',2,16,'用於全駐留原始容量粗估；Strata 走另外的文件配置門檻。'],contextTokens:['Context tokens',256,1000000,'長 context 增加 prefill、狀態和 cache；不能只看短對話 tok/s。'],kvGB:['每請求 KV / state GB',0,512,'手動容量預算；須按架構、context 和精度量測，不套用單一公式。'],runtimeGB:['每請求 runtime 餘量 GB',0,512,'只含 LLM activations、buffer 與 workspace；ASR/TTS 技術卡另外計入，OS 也另外保留。'],concurrency:['同時使用者 / 請求',1,32,'增加記憶體與排隊；Strata 預設逐請求，並行需重測。'],hostReserveGB:['OS / 常駐服務保留 GB',1,128,'全駐留估算保留量；Strata profile 已含其參考主機配置。'],ssdGB:['可用 SSD 空間 GB',1,4096,'包括模型檔、embedding、索引和更新備份。'],speechDeadline:['語音回應期限 ms',50,600000,'由句尾或確認觸發到首音訊／完整回答，需固定計時起點。'],vadMs:['VAD endpoint 預算 ms',0,10000,'若等待使用者停頓，會增加首音訊延遲。'],asrMs:['ASR final 預算 ms',0,10000,'可與 VAD 部分並行；本初步試算採順序保守加總。'],ttsMs:['TTS 首段音訊 ms',0,10000,'串流第一個可播放片段。'],toolMs:['工具 / RAG 預算 ms',0,600000,'包含檢索和工具返回；外部 API 可變延遲另量測。'],replyTokens:['預期回覆 tokens',1,10000,'完整回答驗收時納入；thinking tokens 需另加。'],measuredTps:['實測 decode tok/s',0,1000,'0 表示尚未量測；不能用社群另一部電腦的數值代替。']};
Object.assign(fields,MORE_FIELDS);
const SELECT_FIELDS={cameraPlatform:['相機載體',['fixed','固定工作站'],['uav','無人機 / 空拍'],['robot','移動機器人'],['vehicle','車載相機']],lensClass:['鏡頭 / 取像',['wide','廣角 / 一般鏡頭'],['tele','長焦 / 窄 FOV'],['stereo','Stereo 雙目']],pixelMode:['物件像素取得方式',['measured','實拍量測目標框'],['geometry','由距離 / 實體尺寸 / FOV 粗估']],scaleAnchor:['尺度 / 對照來源',['none','尚未確認'],['calibrated','已標定 / metric checkpoint'],['gnss','GNSS / 地面控制點'],['groundtruth','度量感測器對照']],speechRuntime:['ASR / TTS 部署路徑',['generic','可移植串流 ASR / TTS · 待選模型'],['riva','NVIDIA Riva / GPU'],['qnn','Qualcomm QNN / DSP 路徑']],
 stabilization:['穩定 / 補償',['none','未補償'],['gimbal','機械雲台'],['imu','IMU 融合'],['visual','視覺運動補償']],shutter:['快門',['rolling','Rolling shutter'],['global','Global shutter']],lighting:['影像失效條件',['normal','一般照明'],['lowlight','低照度 / 補光受限'],['reflective','反光 / 透明材質'],['occluded','遮擋 / 低紋理']],depthUse:['距離用途',['relative','前後關係 / 相對深度'],['measure','度量測距'],['avoid','移動避障']],depthMode:['深度與感測路徑',['relative','Depth Anything 相對深度'],['metricmono','度量單目 + 標定'],['stereo','Stereo 雙目'],['tof','ToF / RGB-D'],['fusion','深度 + LiDAR / IMU 融合']],llmProfile:['本地模型',['flash','Qwen3.8-Flash-Next · 125B + 51B'],['next80','Qwen3-Next 80B-A3B'],['small8','小型 8B · 規劃配置'],['small3','小型 3B · 規劃配置']],llmRuntime:['部署框架',['strata','Strata · Qwen3.8 預設'],['llamacpp','llama.cpp / GGUF'],['openvino','OpenVINO / GenAI'],['qnn','Qualcomm QNN / AI Hub'],['tensorrt','TensorRT / TensorRT-LLM'],['vllm','vLLM / CUDA serving']],strataQuant:['Strata 文件配置',['iq2','IQ2_XS · host 48GB 參考'],['iq3','IQ3_S · host 64GB 參考'],['q4','UD-IQ4_XS · host 96GB 參考']],responseMetric:['500 ms 要量什麼？',['firstAudio','首段音訊開始播放'],['fullReply','完整語音回答完成']],audioEnv:['聲學環境',['quiet','近場 / 安靜'],['noisy','產線噪音'],['farfield','遠場 / 多人']],bargeIn:['說話中可打斷',['yes','需要 AEC / barge-in'],['no','不需要']],sensorBus:['感測器接入',['usb','USB / UVC'],['csi','MIPI CSI'],['ethernet','Ethernet / ROS 2']],timestampSync:['時間同步',['unknown','待確認'],['hardware','硬體 timestamp / 同步'],['software','軟體 timestamp']]};
function selectField(key){if(conditionContext([...pool],params).inactive.has(key))return '';const [name,...options]=SELECT_FIELDS[key];return `<div class="field"><label for="p-${key}">${name}</label><select id="p-${key}" data-param="${key}">${options.map(([v,t])=>`<option value="${v}" ${params[key]===v?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function domainBlock(title,body,open=false){return `<details class="domain-block" ${open?'open':''}><summary>${title}</summary>${body}</details>`;}
function renderTuning(){const e=evaluation;let html='';
 if(!pool.size){$('tuning').innerHTML='';return;}
 const context=conditionContext([...pool],params);const visions=context.vision;const points=e.models.some(x=>['tapir','cotracker'].includes(x));const depth=e.depth;const llm=e.llm;const speech=e.speech;
 const suggested=[...new Set(e.scenes.flatMap(c=>SCENE_CONSTRAINTS[c.id]||[]))].filter(id=>!pool.has(id));
 html=`<div class="context-head"><h2>依場景深入釐清</h2><span>${e.scenes.length} 個情境連動</span></div><p class="small-note">僅顯示目前應用需要的條件；進階設定可按需展開。切換場景後，不適用的舊值不參與評估。</p>${suggested.length?`<div class="suggestions"><p>這些條件與目前場景相關</p>${suggested.map(id=>`<button data-add="${id}" data-tip="${esc(CATALOG.find(c=>c.id===id).detail)}">+ ${CATALOG.find(c=>c.id===id).name}</button>`).join('')}</div>`:''}`;
 if(!e.aiot?.standalone||['power','multi','latency'].some(id=>pool.has(id)))html+=domainBlock('共用負載與整機限制',`<div class="fields">${field('inferFps')}${pool.has('yolo')?'<div class="field"><label for="modelSize">YOLOv8 · 640 起測</label><select id="modelSize" data-param="modelSize">'+['n','s','m'].map(x=>`<option value="${x}" ${params.modelSize===x?'selected':''}>YOLOv8${x}</option>`).join('')+'</select></div>':''}${['power','multi','memory','latency'].filter(id=>pool.has(id)).map(id=>field({power:'watts',multi:'streams',memory:'ram',latency:'latency'}[id])).join('')}</div>`,true);
 if(visions)html+=domainBlock('取像：FOV、物件占比與有效像素',`<p class="small-note">確認目標在畫面中是否足夠清楚；只有追蹤或移動取像才需要運動細節。</p><div class="fields">${selectField('cameraPlatform')}${field('sensorFps')}${selectField('pixelMode')}${params.pixelMode==='geometry'?['viewDistance','objectMeters','objectHeightMeters','fov'].map(field).join(''):['objectWidth','objectHeight'].map(field).join('')}</div><details ${params.pixelMode==='geometry'?'open':''}><summary>進階取像與鏡頭條件</summary><div class="inline-presets"><button data-resolution="1280,720">1280×720</button><button data-resolution="1920,1080">1920×1080</button><button data-resolution="3840,2160">3840×2160</button></div><div class="fields">${selectField('lensClass')}${['sensorWidth','sensorHeight',...(params.pixelMode==='geometry'?[]:['viewDistance','fov']),'inputWidth','targetPixels','speed','exposure'].map(field).join('')}</div></details><div id="cameraViz"></div>`,true);
 if(points||pool.has('motion')||e.models.includes('stabilize')||(visions&&params.cameraPlatform!=='fixed'))html+=domainBlock('追蹤：相機晃動、雲台與時間窗',`<div class="fields">${selectField('stabilization')}${selectField('shutter')}${['angularSpeed','imuSyncMs',...(points?['trackingPoints']:[])].map(field).join('')}</div><p class="small-note">gimbal / IMU 不自動視為完美補償。中心近似的角速度位移已加入風險推算；點數改變會增加候選待驗證負載。</p>${points?`<div class="fields">${['maxStep','maxBlur','minFeature'].map(field).join('')}</div>`:''}`,pool.has('motion')||pool.has('gimbaltrack'));
 if(depth)html+=domainBlock('距離：用途與近／遠分段精度',`<div class="fields">${selectField('depthUse')}${selectField('depthMode')}${selectField('scaleAnchor')}${['nearDistance','nearError','farDistance','farError'].map(field).join('')}</div>${context.metric?'<div id="depthViz"></div>':'<p class="small-note">相對深度只比較前後關係；選擇測距或避障後，再填公尺誤差與有效距離。</p>'}${params.depthMode==='stereo'?`<details><summary>Stereo 幾何起測參數</summary><div class="fields">${['baselineMm','focalPx','disparityError'].map(field).join('')}</div></details>`:''}${depth.avoid?`<div class="fields">${['robotSpeed','deceleration','margin'].map(field).join('')}</div><p class="small-note">避障另需控制器與故障處置；近距誤差＋延遲＋制動距離共同決定有效感知範圍。</p>`:''}`,true);
 if(llm)html+=domainBlock('Agent：本地或雲端部署',`<div class="fields">${selectField('llmPlacement')}</div>${params.llmPlacement==='local'?`<div class="fields">${selectField('llmProfile')}${selectField('llmRuntime')}${params.llmRuntime!=='strata'?selectField('llmMemoryPlace'):''}${params.llmRuntime==='strata'?selectField('strataQuant'):field('weightBits')}${['contextTokens','concurrency','ssdGB'].map(field).join('')}</div><div id="llmViz"></div><details><summary>記憶體預算假設</summary><div class="fields">${['kvGB','runtimeGB','hostReserveGB'].map(field).join('')}</div><p class="small-note">全駐留公式使用手動 KV/state 預算；Strata 參考 host 門檻來自專案配置，並非與 GPU 容量簡單相加。長 context／多請求仍需真機 profile。</p></details><a class="source-small" href="https://github.com/Niko1221/Strata" target="_blank" rel="noopener">Strata 實作與硬體條件 ↗</a> · <a class="source-small" href="https://github.com/QwenLM/Qwen3.8-Flash-Next" target="_blank" rel="noopener">Qwen3.8 模型與架構 ↗</a>`:'<p class="small-note">雲端 LLM 不占本地推論容量；語音、檢索與其他模型仍計入。請驗證 API 與網路延遲。</p>'}`,true);
 if(e.models.includes('jev'))html+=domainBlock('Jev：RLCD Qwen 決策部署',`<div class="fields">${selectField('decisionPlacement')}${params.decisionPlacement==='local'?selectField('jevBackend')+['jevParamsB','jevBits','jevStateGB',...(!llm?['concurrency']:[])].map(field).join(''):''}</div><p class="small-note">Jev 依需求採 RLCD Qwen checkpoint；本地必須計入權重、狀態與 runtime。雲端 API 只移除這個模型的推論負載。</p>`,true);
 if(speech)html+=domainBlock('語音：回應期限與聲學環境',`<div class="inline-presets"><span>規劃期限</span>${[500,1000,2000].map(v=>`<button data-deadline="${v}">${v} ms</button>`).join('')}</div><div class="fields">${selectField('responseMetric')}${field('speechDeadline')}${selectField('audioEnv')}${selectField('bargeIn')}${selectField('speechRuntime')}</div><div id="speechViz"></div><details><summary>各階段預算／已測值</summary><div class="fields">${['vadMs','asrMs','ttsMs','toolMs','replyTokens','measuredTps',...(params.responseMetric==='fullReply'?['audioPlaybackMs']:[])].map(field).join('')}</div><p class="small-note">順序保守加總；streaming 重疊需另量測。首音訊期限與完整回答是不同產品要求。</p></details>`,true);
 if(visions||pool.has('lighting'))html+=domainBlock('畫質失效與感測器整合',`<div class="fields">${selectField('lighting')}${selectField('sensorBus')}${selectField('timestampSync')}${e.scenes.some(c=>c.id==='inspection')?field('smallDefectPx'):''}</div>`,false);
 if(e.aiot)html+=renderAiotControls();
 html+=procurementControls()+(!e.aiot?.standalone&&e.models.length?resourceControls():'');
 $('tuning').innerHTML=html;renderDomainVisuals();
}
function renderDomainVisuals(){if(evaluation.aiot){document.querySelectorAll('[data-aiot-working]').forEach(n=>n.textContent=evaluation.aiot.workingMB.toFixed(2)+' MB');document.querySelectorAll('[data-aiot-frame]').forEach(n=>n.textContent=evaluation.aiot.frameMB.toFixed(2)+' MB');}renderResourceVisual();renderCamera();if($('cameraViz')&&Number.isFinite(evaluation.metrics.objectArea))$('cameraViz').innerHTML+=`<div class="object-footprint"><span>${params.sensorWidth}×${params.sensorHeight} · ${params.viewDistance} m · ${params.cameraPlatform}</span><strong>目標 ${evaluation.params.objectWidth.toFixed(1)}×${evaluation.params.objectHeight.toFixed(1)} px · ${evaluation.metrics.objectArea.toFixed(2)}%</strong><small>一般輸入縮圖後寬 ${evaluation.metrics.objectInputWidth.toFixed(1)} px${pool.has('yolo')?`；YOLO 固定 640 起測則 ${evaluation.metrics.detectorObjectWidth.toFixed(1)} px`:""}</small></div>`;const e=evaluation;
 if($('depthViz')&&e.depth)$('depthViz').innerHTML=`<div class="constraint-viz depth-bands"><div><b>${params.nearDistance} m</b><span>要求 ±${params.nearError} m</span><small>近距</small></div><div><b>${params.farDistance} m</b><span>要求 ±${params.farError} m</span><small>遠距</small></div></div><p class="small-note">${params.depthMode==='stereo'?`幾何估算：近 ${e.depth.nearSigma.toFixed(3)} m / 遠 ${e.depth.farSigma.toFixed(3)} m；只含 disparity 幾何項。`:'精度要求未經模型／感測器驗證。'}${e.depth.avoid?` 煞停距離起測 ${e.depth.stopDistance.toFixed(2)} m。`:''}</p>`;
 if($('llmViz')&&e.llm){const l=e.llm;$('llmViz').innerHTML=l.cloud?'<p>雲端 API · 本地模型容量 0 GB；網路延遲待驗證。</p>':l.strata?`<div class="memory-route"><span>GPU<strong>熱門 expert cache</strong><small>桌機參考 ≥12 GB</small></span><i>↔</i><span>CPU / RAM<strong>所有 experts</strong><small>host ${l.hostGB} GB 參考</small></span><i>↔</i><span>SSD<strong>N-gram / 模型檔</strong><small>${params.ssdGB} GB 預算</small></span></div>`:`<div class="constraint-viz"><strong>全駐留粗估 ${l.fullGB.toFixed(1)} GB</strong><p class="small-note">原始權重 ${l.weightsGB.toFixed(1)} GB + 手動 cache / runtime / OS 預算；量化 metadata 與框架開銷仍需量測。</p></div>`;}
 if($('speechViz')&&e.speech){const s=e.speech;$('speechViz').innerHTML=`<div class="latency-budget"><span>VAD ${params.vadMs}</span><span>ASR ${params.asrMs}</span><span>工具 ${params.toolMs}</span><span>TTS ${params.ttsMs}</span><strong class="${s.remainingMs<=0?'bad':''}">LLM 剩餘 ${Math.max(0,s.remainingMs).toFixed(0)} ms</strong></div><p class="small-note">前段預算 ${s.frontMs} ms${s.decodeMs?` + decode ${s.decodeMs.toFixed(0)} ms`:''}${s.playbackMs?` + 播放 ${s.playbackMs} ms`:''}；首 token 與 prefill 尚需測量。</p>`;}
}
function renderTrace(){$('trace').innerHTML=evaluation.requirements.map(r=>`<div class="requirement-status"><i class="dot ${r.state}"></i><strong>${r.name}</strong><span>${esc(r.text)}</span></div>`).join('');}
function deviceArt(d){const src=DEVICE_IMAGES[d?.id];return src?`<figure class="hardware-photo"><img src="${src}" alt="${esc(d.name)}官方實體產品／封裝圖" loading="lazy"><figcaption>${esc((DEVICE_CAPTIONS[d.id]||'官方產品圖 · '+d.vendor))}</figcaption></figure>`:'<p class="small-note">此配置照片待供應商確認，查看官方產品。</p>';}
function candidateExplanation(d){const e=evaluation,w=e.winner;if(d.blocked.length)return d.blocked;
 if(!w)return ['共同需求尚待釐清，這是裝置路徑預檢，不是最終推薦。'];
 if(d.id===w.id)return d.why.length?d.why:['此配置暫列起測首選；仍須真機驗證。'];
 if(params.costPriority==='cost'&&d.costRank>w.costRank)return [`採購等級 ${(COST_BANDS[d.costBand]?.label||'—')}，高於首選 ${COST_BANDS[w.costBand].label}；目前以採購等級優先。`,...d.why.slice(0,1)];
 if(d.score===w.score&&d.costRank>w.costRank)return [`技術優先權同分；採購等級 ${(COST_BANDS[d.costBand]?.label||'—')} 高於首選 ${COST_BANDS[w.costBand].label}。`,...d.why.slice(0,1)];
 if(d.score===w.score)return [`與首選同為 ${d.score} 規劃優先權，依資料順序暫列後位；兩者均需 PoC。`,...d.why.slice(0,1)];
 return [`規劃優先權 ${d.score}，低於首選 ${w.score}；${w.why[0]?.replace(/（優先權.*$/,'')||'首選的部署路徑較符合目前規劃'}。`,...d.why.slice(0,1)];
}
function candidateBranches(){const e=evaluation;return `<div class="candidate-tree"><div class="tree-root">逐裝置檢查：框架 → 並存 RAM / VRAM → I/O → 功耗 → 採購等級 → 排名</div>${e.candidates.map(d=>{const chosen=e.winner?.id===d.id;const state=d.blocked.length?'rejected':chosen?'chosen':'secondary';return `<div class="candidate-branch ${state}"><div class="branch-line"></div><div class="branch-content"><div class="branch-title"><strong>${esc(d.name)}</strong><span>${d.blocked.length?'排除':chosen?'排名 #1':e.winner?'保留 / 次順位':'預檢'}</span></div><div class="gate-tags"><span>${d.blocked.some(t=>/Strata|QNN|Riva|框架|CUDA|OpenVINO|部署證據/.test(t))?'框架不合':'框架待驗證'}</span><span>${d.blocked.some(t=>/RAM|VRAM|GB/.test(t))?'容量不合':'容量待量測'}</span><span>${d.blocked.some(t=>/功耗|W 不足/.test(t))?'功耗不合':'功耗待量測'}</span><span>採購 ${(COST_BANDS[d.costBand]?.label||'—')}${d.blocked.some(t=>/採購等級/.test(t))?' · 超出上限':''}</span>${d.id===params.profileDevice?`<span>${d.blocked.some(t=>/合計運算時間/.test(t))?'運算時間不合':'運算時間待驗證'}</span>`:''}${d.blocked.some(t=>/CSI/.test(t))?'<span>I/O 不合</span>':''}</div>${candidateExplanation(d).slice(0,2).map(t=>`<p>${esc(t)}</p>`).join('')}<button class="text-button" data-device="${d.id}">全部理由與版本查核</button></div></div>`;}).join('')}</div>`;}
function productFlow(){const e=evaluation;const route=e.aiot?AIOT.T(e.aiot.standalone?(e.aiot.muse?'service':'standalone'):'host'):e.llm?(e.llm.cloud?'雲端 API':`本地 Agent / ${params.llmRuntime}`):e.depth?`度量／感測融合 / ${params.depthMode}`:e.models.some(m=>['tapir','cotracker'].includes(m))?'時序追蹤 / 運動補償':'視覺 / 固定管線';return `<div class="result-section final-flow"><h3>完整產品選型思路</h3><div class="product-flow"><div class="flow-box"><b>產品輸出與失敗代價</b><small>${e.scenes.map(s=>s.name).join(' + ')||'先加入場景'}</small></div><i>↓</i><div class="flow-split"><span><b>感知條件</b><small>${e.depth?'公尺精度 / 煞停':e.speech?'聲學 / 句尾判定':'FOV / 像素 / 晃動'}</small></span><span><b>時間與資源</b><small>${e.speech?`${params.speechDeadline} ms 回應`:`${e.aiot?.cv?params.mcuFps:params.inferFps} FPS 更新`} / ${pool.has('power')?`${params.watts} W`:'功耗待定'}</small></span></div><i>↓</i><div class="flow-box"><b>技術與部署路徑</b><small>${route}<br>${e.models.map(m=>CATALOG.find(c=>c.id===m).name).join(' + ')||'待選擇技術'}</small></div><i>↓</i><div class="flow-gate ${e.issues.length?'bad':''}"><b>需求相容？</b><small>${e.issues.length?`${e.issues.length} 項輸入／路徑衝突 → 返回釐清`:'輸入預檢未發現衝突 → 進入裝置評估'}</small></div><i>↓</i><div class="flow-split"><span><b>硬性篩除</b><small>RAM / VRAM / 框架<br>${e.candidates.filter(d=>d.blocked.length).length} 個候選排除</small></span><span><b>比較優先權</b><small>部署證據 / I/O<br>並存模型與容量餘裕 / 採購等級</small></span></div><i>↓</i>${candidateBranches()}<i>↓</i><div class="flow-box"><b>${e.winner?e.winner.name:'目前沒有可推薦組合'}</b><small>${e.winner?'候選 #1 · 附條件的 PoC 起點':'修正約束後重新排名'}</small></div><i>↓</i><div class="flow-box verification"><b>真機驗收後才定型</b><small>精度 → P95 / FPS → 峰值 RAM<br>整機功耗 → 熱穩態 → 失效處置</small></div></div><button class="text-button" data-export="drawio">匯出這次完整流程 .drawio</button></div>`;}

