function budgetInput(t,key,label,value){return `<label>${label}<input type="number" min="0" step="any" data-budget="${t.id}" data-budget-key="${key}" value="${value??''}" aria-label="${esc(t.id+' '+label)}" placeholder="${key==='timeMs'?'未測':''}"></label>`;}
function resourceControls(){const r=evaluation.resources;return domainBlock('同時運行：模型與 GPU 資源池',`<div class="resource-summary" id="resourceSummary"><span>全部並存<strong>${r.totalGB.toFixed(1)} GB</strong></span><span>Host 規劃<strong>${r.hostGB.toFixed(1)} GB</strong></span><span>Accelerator 規劃<strong>${r.acceleratorGB.toFixed(1)} GB</strong></span></div><p class="small-note">權重一份共用；state × 相機路數／請求並行數。數值是可編輯規劃包絡，不是實測。統一記憶體檢查總量；獨顯分查 RAM / VRAM。</p><div class="fields">${field('systemReserveGB')}${field('agentRateHz')}${evaluation.llm&&evaluation.llm.cloud?field('concurrency'):''}${selectField('profileDevice')}${field('utilLimit')}</div>${evaluation.llm&&!evaluation.llm.cloud&&evaluation.llm.strata?`<div class="fields">${field('strataResidentGB')}${field('strataGpuGB')}</div>`:''}<div id="resourceViz"></div><details><summary>逐模型編輯權重、狀態與運算時間</summary><div class="task-budgets">${r.tasks.map(t=>t.id==='jev'?`<p>Jev 權重 ${t.weightGB.toFixed(1)} GB + state ${t.stateGB} × ${t.copies}；以上方 checkpoint 設定調整。</p>`:`<div class="task-budget"><strong>${esc(CATALOG.find(c=>c.id===t.id).name)} <small data-task-copies="${t.id}">× ${t.copies}</small></strong><div class="budget-fields">${budgetInput(t,'weightGB','共用權重 GB',t.weightGB)}${budgetInput(t,'stateGB','每路 state GB',t.stateGB)}${budgetInput(t,'rateHz','更新 Hz',t.rateHz)}${budgetInput(t,'timeMs','參考裝置每次 ms',t.timeMs)}<label>執行位置<select data-budget="${t.id}" data-budget-key="place"><option value="host" ${t.place==='host'?'selected':''}>Host</option><option value="accelerator" ${t.place==='accelerator'?'selected':''}>Accelerator</option></select></label></div></div>`).join('')}</div></details><p class="small-note">GPU 時間＝Σ（每次 ms × Hz × 路數）÷1000；只用於參考裝置，不以 TOPS 比例外推。未測任務與 LLM expert cache 尚待整體 profile。</p>`,false);}
function renderResourceVisual(){const r=evaluation.resources;if($('resourceSummary'))$('resourceSummary').innerHTML=`<span>全部並存<strong>${r.totalGB.toFixed(1)} GB</strong></span><span>Host 規劃<strong>${r.hostGB.toFixed(1)} GB</strong></span><span>Accelerator 規劃<strong>${r.acceleratorGB.toFixed(1)} GB</strong></span>`;document.querySelectorAll('[data-budget-key="rateHz"]').forEach(n=>{const task=r.tasks.find(t=>t.id===n.dataset.budget);if(task&&params.modelBudgets[task.id]?.rateHz===undefined)n.value=task.rateHz;});document.querySelectorAll('[data-task-copies]').forEach(n=>{const task=r.tasks.find(t=>t.id===n.dataset.taskCopies);if(task)n.textContent='× '+task.copies;});if(!$('resourceViz'))return;const d=DEVICES.find(d=>d.id===params.profileDevice);$('resourceViz').innerHTML=`<div class="load-meter"><span>${esc(d?.name||'')} · 已填 accelerator profile</span><meter min="0" max="1" value="${Math.min(r.occupancy,1)}">${Math.round(r.occupancy*100)}%</meter><b>${Math.round(r.occupancy*100)}% / 上限 ${Math.round(r.utilLimit*100)}%</b><small>${r.allTimed?'已填此列表的時間；整體仍需量測':'尚有未測任务，不能宣稱運算負載通過'}</small></div>`;}



// Map validation rules to editable controls, never to hidden, inactive parameters.
function conflictControls(issue){
 const map={exposure:['exposure','sensorFps'],fps:['inferFps','sensorFps'],step:['inferFps','sensorFps','speed','angularSpeed','fov','maxStep'],blur:['exposure','speed','angularSpeed','maxBlur'],feature:['inputWidth','targetPixels','minFeature'],depthrange:['nearDistance','farDistance'],metric:['depthMode','depthUse'],sensorpath:['depthMode'],depthtech:['depthMode'],scale:['scaleAnchor'],depthprecision:['baselineMm','focalPx','disparityError','nearError','farError'],stop:['robotSpeed','latency','deceleration','margin','farDistance'],runtime:['llmRuntime','llmProfile'],ssd:['ssdGB','strataQuant'],speech:['speechDeadline','vadMs','asrMs','toolMs','ttsMs','replyTokens','measuredTps','audioPlaybackMs'],offline:['decisionPlacement','llmPlacement'],motiontech:['stabilization']};
 let keys=issue.fields||map[issue.code]||[];
 if(issue.code==='geometry')keys=params.pixelMode==='geometry'?['objectMeters','objectHeightMeters','viewDistance','fov']:['objectWidth','sensorWidth','objectHeight','sensorHeight'].filter(k=>k.endsWith('Width')?Number(params.objectWidth)>Number(params.sensorWidth):Number(params.objectHeight)>Number(params.sensorHeight));
 if(issue.code==='input'&&!keys.length){const key=issue.text.split(' ')[0];keys=Object.hasOwn(DEFAULTS,key)?[key]:issue.text.includes('YOLO')?['modelSize']:issue.text.includes('追蹤點數')?['trackingPoints']:issue.text.includes('context')?['concurrency','contextTokens']:issue.text.includes('相機路數')?['streams']:[];}
 let controls=keys.flatMap(k=>Array.from(document.querySelectorAll(`[data-param="${k}"]`)));
 if(issue.code==='resourceinput')controls=issue.task?Array.from(document.querySelectorAll(`[data-budget="${issue.task}"]`)):Array.from(document.querySelectorAll('[data-param="profileDevice"]'));
 if(issue.code==='costinput')controls=Array.from(document.querySelectorAll(`[data-cost="${issue.device}"]`));
 return controls.length?controls:[$('pool')].filter(Boolean);
}
function syncConflictHighlights(){
 document.querySelectorAll('[data-conflict-mark]').forEach(n=>{n.classList.remove('condition-conflict','conflict-section','conflict-attention');n.removeAttribute('data-conflict-mark');n.removeAttribute('aria-describedby');});
 evaluation.issues.forEach((issue,index)=>conflictControls(issue).forEach(n=>{
  n.classList.add('condition-conflict');n.setAttribute('data-conflict-mark','');
  const refs=n.getAttribute?.('aria-describedby')||'';n.setAttribute('aria-describedby',(refs+' conflict-message-'+index).trim());
  for(let parent=n.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS'){parent.classList.add('conflict-section');parent.setAttribute('data-conflict-mark','');}
 }));
}
function focusConflict(index){
 const issue=evaluation.issues[index];if(!issue)return;
 if(!$('drawer').hidden)closeDrawer();
 const controls=conflictControls(issue);
 controls.forEach(n=>{for(let parent=n.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;});
 const first=controls[0];if(!first)return;
 first.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});
 first.focus({preventScroll:true});
 controls.forEach(n=>{n.classList.remove('conflict-attention');void n.offsetWidth;n.classList.add('conflict-attention');});
 announce(issue.text);
}


